import React, { useState } from "react";
import categories from "../data/categories";
import { ArrowLeft, ArrowRight, categoryIcon } from "./Icons";
import "./Hero.css";

export default function Hero() {
  const [index, setIndex] = useState(1); // start on "Healthcare" like the reference screenshot

  const active = categories[index];
  const go = (dir) => {
    setIndex((prev) => (prev + dir + categories.length) % categories.length);
  };

  return (
    <section className="hero">
      <div className="hero__panel">
        <div className="hero__text" key={active.key}>
          <h2>{active.title}</h2>
          <p>{active.description}</p>
          <button className="hero__cta">Know More</button>
        </div>

        <div className="hero__nav">
          <button aria-label="Previous" onClick={() => go(-1)}>
            <ArrowLeft color="#fff" size={16} />
          </button>
          <button aria-label="Next" onClick={() => go(1)}>
            <ArrowRight color="#fff" size={16} />
          </button>
        </div>
      </div>

      <div className="hero__image" style={{ background: `linear-gradient(135deg, ${active.color}, ${active.colorDark})` }}>
        <div className="hero__image-icon">{categoryIcon(active.key, 140)}</div>
      </div>

      <div
        className="hero__bar"
        style={{ background: `linear-gradient(90deg, ${active.color}, ${active.colorDark})` }}
      >
        {categories.map((cat, i) => (
          <button
            key={cat.key}
            className={`hero__bar-item ${i === index ? "hero__bar-item--active" : ""}`}
            onClick={() => setIndex(i)}
          >
            {categoryIcon(cat.key, 28)}
            <span>{cat.label.toUpperCase()}</span>
          </button>
        ))}
      </div>
    </section>
  );
}
